  {href:"../coProsperitySphereReference%20-%20AltWWII.md",label:"Co-Prosperity Sphere Reference — Azad Hind and the Indian successor system"},
  {href:"../settingBible%20-%20AltWWII.md",label:"Setting Bible — Indian successor states and Japanese strategy"},
  {href:"../settingTimeline%20-%20AltWWII.md",label:"Setting Timeline — Indian wars, 1948–1965"},
  {href:"../transcript.md",label:"Master Transcript — Azad Hind consolidation, Delhi Campaign, and Northern Indian War"}
